#!/usr/bin/env python3
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parent

CHECKS = [
    {
        "path": "AGENTS.md",
        "need": ["## Rules", "### tryout-marker", "TRYOUT_RULE_MARKER"],
    },
    {
        "path": "CLAUDE.md",
        "need": ["Generated by agnostic-ai"],
        "absent": ["TRYOUT_RULE_MARKER", "@AGENTS.md"],
    },
    {
        "path": ".claude/rules/tryout-marker.md",
        "need": ["paths:", '"**/*"', "TRYOUT_RULE_MARKER"],
    },
    {
        "path": ".claude/agents/tryout-reader.md",
        "need": [
            "name: tryout-reader",
            "description:",
            "tools:",
            "- Read",
            "- Grep",
            "- Bash",
            "TRYOUT_AGENT_MARKER",
        ],
    },
    {
        "path": ".claude/skills/tryout-checklist/SKILL.md",
        "need": ["name: tryout-checklist", "description:", "TRYOUT_SKILL_MARKER"],
    },
    {
        "path": ".codex/agents/tryout-reader.toml",
        "need": [
            'name = "tryout-reader"',
            'description = "',
            "developer_instructions",
            "TRYOUT_AGENT_MARKER",
        ],
        "absent": ["can"],
    },
    {
        "path": ".agents/skills/tryout-checklist/SKILL.md",
        "need": ["name: tryout-checklist", "description:", "TRYOUT_SKILL_MARKER"],
    },
    {
        "path": ".cursor/rules/tryout-marker.mdc",
        "need": ["description:", "globs:", "alwaysApply: true", "TRYOUT_RULE_MARKER"],
    },
    {
        "path": ".cursor/agents/tryout-reader.md",
        "need": ["name: tryout-reader", "description:", "TRYOUT_AGENT_MARKER"],
        "absent": ["tools:", "can:"],
    },
    {
        "path": ".cursor/skills/tryout-checklist/SKILL.md",
        "need": ["name: tryout-checklist", "description:", "TRYOUT_SKILL_MARKER"],
    },
]

SKILL_PATHS = [
    ".claude/skills/tryout-checklist/SKILL.md",
    ".agents/skills/tryout-checklist/SKILL.md",
    ".cursor/skills/tryout-checklist/SKILL.md",
]


def fail(message):
    print(message, file=sys.stderr)
    return 1


def main():
    errors = 0
    for item in CHECKS:
        path = ROOT / item["path"]
        if not path.is_file():
            errors += fail(f"missing {item['path']}")
            continue
        text = path.read_text()
        for needle in item["need"]:
            if needle not in text:
                errors += fail(f"{item['path']} lacks {needle}")
        for needle in item.get("absent", []):
            if needle in text:
                errors += fail(f"{item['path']} still has {needle}")
        if item["path"].endswith("/SKILL.md"):
            folder = path.parent.name
            if f"name: {folder}\n" not in text:
                errors += fail(f"{item['path']} name does not match {folder}")

    bodies = [(ROOT / rel).read_text() for rel in SKILL_PATHS]
    if len(set(bodies)) != 1:
        errors += fail("skill copies differ")

    if errors:
        print(f"{errors} checks failed")
        return 1
    print(f"{len(CHECKS)} files matched")
    return 0


if __name__ == "__main__":
    sys.exit(main())
